() => {
  const btns = Array.from(document.querySelectorAll('button[title]'));
  const b = btns.find(x => x.title.startsWith('数据自省：已开启'));
  if (!b) return { found: false };
  const cs = getComputedStyle(b);
  const svg = b.querySelector('svg');
  const svgColor = svg ? getComputedStyle(svg).color : null;
  return {
    found: true,
    title: b.title,
    className: b.className,
    color: cs.color,
    backgroundColor: cs.backgroundColor,
    borderColor: cs.borderColor,
    svgColor,
    inCard: b.closest('[class*="card"], div') ? 'yes' : 'no'
  };
}

() => {
  const btns = Array.from(document.querySelectorAll('button[title]'));
  const b = btns.find(x => x.title.startsWith('数据自省：已开启'));
  const svg = b.querySelector('svg');
  return {
    svgPaths: svg ? Array.from(svg.querySelectorAll('path,circle,line')).map(e => e.outerHTML).join(' ').slice(0, 400) : null,
    cardName: (() => {
      let p = b.closest('div');
      while (p && !/客户拜访管理/.test(p.textContent || '')) p = p.parentElement;
      return p ? '客户拜访管理 card contains button' : 'not in card';
    })()
  };
}

