() => {
  // 点赞沉淀 badge color
  const badges = Array.from(document.querySelectorAll('span')).filter(s => s.textContent.trim() === '点赞沉淀');
  const badgeInfo = badges.map(b => ({ cls: b.className, color: getComputedStyle(b).color, bg: getComputedStyle(b).backgroundColor }));
  // SQL 样例库 tab icon color
  const tab = Array.from(document.querySelectorAll('button')).find(b => b.textContent.includes('SQL 样例库'));
  const svg = tab ? tab.querySelector('svg') : null;
  const tabInfo = tab ? { cls: tab.className, svgColor: svg ? getComputedStyle(svg).color : null } : null;
  return { badgeCount: badges.length, badgeInfo: badgeInfo.slice(0, 2), tabInfo };
}

