() => {
  return new Promise(resolve => {
    const start = performance.now();
    requestAnimationFrame(() => {
      resolve({ rAFfired: true, ms: Math.round(performance.now() - start), hidden: document.hidden, visibility: document.visibilityState });
    });
    setTimeout(() => resolve({ rAFfired: false, ms: 3000, hidden: document.hidden, visibility: document.visibilityState }), 3000);
  });
}

() => {
  // Shim rAF so stability waits complete even in hidden tab
  window.requestAnimationFrame = (cb) => setTimeout(() => cb(performance.now()), 20);
  window.cancelAnimationFrame = (id) => clearTimeout(id);
  if (document.documentElement.requestAnimationFrame) {
    // also neutralize CSS animations
    if (!document.getElementById('__noanim')) {
      const s = document.createElement('style');
      s.id = '__noanim';
      s.textContent = '*,*::before,*::after{animation:none !important;transition:none !important;}';
      document.head.appendChild(s);
    }
  }
  return 'shim installed';
}

